import{_ as t,o as n,c as s,a3 as r}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Centers","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/centers.md","filePath":"user/admin/centers.md"}'),a={name:"user/admin/centers.md"};function o(i,e,c,d,g,h){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="centers" tabindex="-1">Centers <a class="header-anchor" href="#centers" aria-label="Permalink to &quot;Centers&quot;">​</a></h1><h2 id="creating-and-reviewing-centers" tabindex="-1">Creating and reviewing centers <a class="header-anchor" href="#creating-and-reviewing-centers" aria-label="Permalink to &quot;Creating and reviewing centers&quot;">​</a></h2><p>Centers register themselves, or you can create one from <strong>Centers → New</strong>. Each center has a <strong>state</strong> that you control and a <strong>status</strong> that the center controls.</p><table tabindex="0"><thead><tr><th></th><th>Values</th><th>Who changes it</th></tr></thead><tbody><tr><td><strong>State</strong></td><td><strong>Pending</strong>, <strong>Active</strong>, <strong>Blocked</strong></td><td>Admins only</td></tr><tr><td><strong>Status</strong></td><td><strong>Visible</strong>, <strong>Invisible</strong></td><td>The center (admins can change it too)</td></tr></tbody></table><ul><li>A center must be <strong>Active</strong> before its team can use the dashboard.</li><li>Clients only see centers that are <strong>Visible and Active</strong>.</li><li><strong>Blocked</strong> stops the center from operating. Its data is kept.</li></ul><p>Only admins can change state, status, custom site and domain.</p><p>The centers list shows the newest centers first. You can sort it by <strong>Center</strong> (name), <strong>Points</strong> or <strong>Created</strong>; see <a href="./getting-around#lists">Lists</a>.</p><p>Deleted centers are hidden from the list. You can filter the list to include them or to show only deleted centers, and open a deleted center to see its details. A deleted center cannot be edited.</p><p>With the <strong>centers.restore</strong> permission you can <strong>restore</strong> a deleted center. It comes back as it was, with the same state, status, owner and team, and their permissions. Team members whose accounts were removed with the center can sign in again. Centers deleted before this was possible come back without a team.</p><p><strong>Points</strong> decide how high a center appears when clients browse the most popular centers. Admins can set a center&#39;s points when editing it; the center&#39;s team cannot.</p><h2 id="what-you-can-open-for-a-center" tabindex="-1">What you can open for a center <a class="header-anchor" href="#what-you-can-open-for-a-center" aria-label="Permalink to &quot;What you can open for a center&quot;">​</a></h2><p>From a center you can open (and, with the right permission, edit) the same things its team uses:</p><ul><li><strong>Services</strong> of every type, and trainers, service blocks and periods</li><li><strong>Reservations</strong>, including creating, cancelling, completing, marking no-show and rescheduling on its behalf</li><li><strong>Purchases</strong> and the center&#39;s <strong>ledger</strong></li><li><strong>Clients</strong>, <strong>blocked clients</strong>, <strong>packages</strong> and <strong>client memberships</strong></li><li><strong>Ratings</strong>, newest first or highest first</li><li><strong>Subscription</strong>, social links and site theme</li></ul><h2 id="managing-a-center-s-users" tabindex="-1">Managing a center&#39;s users <a class="header-anchor" href="#managing-a-center-s-users" aria-label="Permalink to &quot;Managing a center&#39;s users&quot;">​</a></h2><p>The <strong>Users</strong> tab of a center lists its team: the primary user (the owner) first, then each staff member with their status, linked trainer and permissions. With the <strong>centers.update</strong> permission you can:</p><ul><li><strong>Add</strong> a user with a name, phone, linked trainer, status and any permissions. If the phone already has an account, that account is added and keeps its name.</li><li><strong>Edit</strong> a user&#39;s name, phone, trainer, status and permissions. A new phone must be verified again and the user is signed out on every device.</li><li><strong>Remove</strong> a user. They lose access to the center; an account left without any center is deleted.</li></ul><p>For the primary user you can only change the name and phone. The primary user always has every permission and cannot be removed.</p><h2 id="generating-a-login-code-for-a-center-user" tabindex="-1">Generating a login code for a center user <a class="header-anchor" href="#generating-a-login-code-for-a-center-user" aria-label="Permalink to &quot;Generating a login code for a center user&quot;">​</a></h2><p>If someone on a center&#39;s team is not receiving the SMS, open the center, choose <strong>Generate OTP</strong>, and pick the user. You get a new 4-digit code to read to them. No SMS is sent, the code is shown only once, and it expires after 5 minutes. This needs the <strong>otps.create</strong> permission.</p><h2 id="cities-and-tags" tabindex="-1">Cities and tags <a class="header-anchor" href="#cities-and-tags" aria-label="Permalink to &quot;Cities and tags&quot;">​</a></h2><p>Manage the <strong>cities</strong> (with their coverage radius) and <strong>tags</strong> that centers choose from, under <strong>Cities</strong> and <strong>Tags</strong>.</p><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p>You can export the centers list, and a center&#39;s purchases and ledger. See <a href="./analytics">Analytics and exports</a>.</p>',23)])])}const p=t(a,[["render",o]]);export{u as __pageData,p as default};
